// Test: keyOfListClassConstant
namespace PsalmTest_key_of_array_1 {
    class A {
        const FOO = [
            "bar"
        ];
        /** @return key-of<A::FOO> */
        public function getKey() {
            return 0;
        }
    }

    assertType('0', (new A())->getKey());
}

// Test: keyOfAssociativeArrayClassConstant
namespace PsalmTest_key_of_array_2 {
    class A {
        const FOO = [
            "bar" => 42
        ];
        /** @return key-of<A::FOO> */
        public function getKey() {
            return "bar";
        }
    }

    assertType("'bar'", (new A())->getKey()); // SKIP: the operand's class resolves to the first `A` in the file
}

// Test: allKeysOfAssociativeArrayPossible
namespace PsalmTest_key_of_array_3 {
    class A {
        const FOO = [
            "bar" => 42,
            "adams" => 43,
        ];
        /** @return key-of<A::FOO> */
        public function getKey(bool $adams) {
            if ($adams) {
                return "adams";
            }
            return "bar";
        }
    }

    assertType("'adams'|'bar'", (new A())->getKey(true)); // SKIP: the operand's class resolves to the first `A` in the file
}

// Test: keyOfAsArray
namespace PsalmTest_key_of_array_4 {
    class A {
        /** @var array */
        const FOO = [
            "bar" => 42,
            "adams" => 43,
        ];
        /** @return key-of<self::FOO>[] */
        public function getKey() {
            return array_keys(self::FOO);
        }
    }

    assertType("array<'bar'|'adams'>", (new A())->getKey());
}

// Test: keyOfArrayLiteral
namespace PsalmTest_key_of_array_5 {
    /**
     * @return key-of<array<int, string>>
     */
    function getKey() {
        return 32;
    }

    assertType('int', getKey());
}

// Test: keyOfUnionArrayLiteral
namespace PsalmTest_key_of_array_6 {
    /**
     * @return key-of<array<int, string>|array<string, string>>
     */
    function getKey(bool $asString) {
        if ($asString) {
            return "42";
        }
        return 42;
    }

    assertType('int|string', getKey(true));
}

// Test: keyOfUnionListAndKeyedArray
namespace PsalmTest_key_of_array_7 {
    /**
     * @return key-of<list<int>|array{a: int, b: int}>
     */
    function getKey(bool $asInt) {
        if ($asInt) {
            return 42;
        }
        return "a";
    }

    assertType("'a'|'b'|int", getKey(true));
}

